public static boolean treeEqual(BinNode<Integer> t) {
    int r0 = countRemainder(t, 0);
    int r1 = countRemainder(t, 1);
    int r2 = countRemainder(t, 2);
    return r0 == r1 && r1 == r2;
}

// פעולת עזר: כמה ערכים בעץ t מתחלקים ב-3 עם שארית r
public static int countRemainder(BinNode<Integer> t, int r) {
    if (t == null) {
        return 0;
    }
    int count = countRemainder(t.getLeft(), r) + countRemainder(t.getRight(), r);
    if (t.getValue() % 3 == r) {
        count++;
    }
    return count;
}

